begin;
create table if not exists public.mme_inventory_locations(location_id uuid primary key default gen_random_uuid(),location_code text not null unique,location_name text not null,location_type text not null check(location_type in('store','warehouse','stockroom','in_transit','repair','quarantine')),address_text text,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.mme_inventory_items(inventory_item_id uuid primary key default gen_random_uuid(),sku text not null unique,product_name text not null,brand text,category text,unit_of_measure text not null default 'each',track_serial boolean not null default false,track_imei boolean not null default false,reorder_point integer not null default 0 check(reorder_point>=0),standard_cost numeric(14,2) check(standard_cost is null or standard_cost>=0),is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.mme_inventory_serials(serial_id uuid primary key default gen_random_uuid(),inventory_item_id uuid not null references public.mme_inventory_items(inventory_item_id),serial_number text not null unique,imei text unique,condition_grade text not null default 'ungraded' check(condition_grade in('new','open_box','A','B','C','parts','ungraded')),ownership_status text not null default 'owned' check(ownership_status in('owned','consignment','customer_owned','vendor_owned')),serial_status text not null default 'available' check(serial_status in('available','reserved','sold','in_transit','repair','quarantine','returned','retired')),location_id uuid references public.mme_inventory_locations(location_id),received_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.mme_inventory_balances(balance_id uuid primary key default gen_random_uuid(),inventory_item_id uuid not null references public.mme_inventory_items(inventory_item_id),location_id uuid not null references public.mme_inventory_locations(location_id),on_hand integer not null default 0 check(on_hand>=0),reserved integer not null default 0 check(reserved>=0 and reserved<=on_hand),updated_at timestamptz not null default now(),unique(inventory_item_id,location_id));
create table if not exists public.mme_inventory_movements(movement_id uuid primary key default gen_random_uuid(),inventory_item_id uuid not null references public.mme_inventory_items(inventory_item_id),serial_id uuid references public.mme_inventory_serials(serial_id),from_location_id uuid references public.mme_inventory_locations(location_id),to_location_id uuid references public.mme_inventory_locations(location_id),movement_type text not null check(movement_type in('receipt','sale','return','transfer_out','transfer_in','adjustment_in','adjustment_out','reservation','release','repair','writeoff')),quantity integer not null check(quantity>0),unit_cost numeric(14,2),source_type text,source_reference text,reason text,actor_auth_user_id uuid not null,created_at timestamptz not null default now());
create index if not exists mme_inventory_movements_item_time_idx on public.mme_inventory_movements(inventory_item_id,created_at desc);
create table if not exists public.mme_inventory_reservations(reservation_id uuid primary key default gen_random_uuid(),inventory_item_id uuid not null references public.mme_inventory_items(inventory_item_id),location_id uuid not null references public.mme_inventory_locations(location_id),serial_id uuid references public.mme_inventory_serials(serial_id),quantity integer not null check(quantity>0),reference_type text not null,reference_id text not null,reservation_status text not null default 'active' check(reservation_status in('active','fulfilled','released','expired')),expires_at timestamptz,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_inventory_transfers(transfer_id uuid primary key default gen_random_uuid(),transfer_number text not null unique,from_location_id uuid not null references public.mme_inventory_locations(location_id),to_location_id uuid not null references public.mme_inventory_locations(location_id),transfer_status text not null default 'draft' check(transfer_status in('draft','approved','shipped','partially_received','received','cancelled')),created_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,shipped_at timestamptz,received_at timestamptz,created_at timestamptz not null default now(),check(from_location_id<>to_location_id));
create table if not exists public.mme_inventory_transfer_lines(transfer_line_id uuid primary key default gen_random_uuid(),transfer_id uuid not null references public.mme_inventory_transfers(transfer_id),inventory_item_id uuid not null references public.mme_inventory_items(inventory_item_id),serial_id uuid references public.mme_inventory_serials(serial_id),quantity integer not null check(quantity>0),received_quantity integer not null default 0 check(received_quantity>=0 and received_quantity<=quantity));
create table if not exists public.mme_inventory_counts(inventory_count_id uuid primary key default gen_random_uuid(),count_number text not null unique,location_id uuid not null references public.mme_inventory_locations(location_id),count_status text not null default 'draft' check(count_status in('draft','in_progress','submitted','approved','posted','cancelled')),created_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,created_at timestamptz not null default now());
create table if not exists public.mme_inventory_count_lines(count_line_id uuid primary key default gen_random_uuid(),inventory_count_id uuid not null references public.mme_inventory_counts(inventory_count_id),inventory_item_id uuid not null references public.mme_inventory_items(inventory_item_id),expected_quantity integer not null check(expected_quantity>=0),counted_quantity integer not null check(counted_quantity>=0),variance integer generated always as(counted_quantity-expected_quantity) stored);
create table if not exists public.mme_inventory_receipts(receipt_id uuid primary key default gen_random_uuid(),receipt_number text not null unique,purchase_order_reference text,vendor_reference text,location_id uuid not null references public.mme_inventory_locations(location_id),receipt_status text not null default 'draft' check(receipt_status in('draft','received','posted','cancelled')),received_by_auth_user_id uuid not null,received_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.mme_inventory_receipt_lines(receipt_line_id uuid primary key default gen_random_uuid(),receipt_id uuid not null references public.mme_inventory_receipts(receipt_id),inventory_item_id uuid not null references public.mme_inventory_items(inventory_item_id),serial_id uuid references public.mme_inventory_serials(serial_id),quantity integer not null check(quantity>0),unit_cost numeric(14,2) check(unit_cost is null or unit_cost>=0));
create table if not exists public.mme_inventory_alerts(alert_id uuid primary key default gen_random_uuid(),inventory_item_id uuid not null references public.mme_inventory_items(inventory_item_id),location_id uuid references public.mme_inventory_locations(location_id),alert_type text not null check(alert_type in('low_stock','out_of_stock','negative_adjustment','serial_mismatch','shrinkage')),severity text not null default 'info' check(severity in('info','warning','critical')),alert_status text not null default 'open' check(alert_status in('open','acknowledged','resolved')),details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists public.mme_inventory_audit_events(audit_event_id uuid primary key default gen_random_uuid(),entity_type text not null,entity_id uuid not null,action text not null,actor_auth_user_id uuid not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function public.mme_inventory_adjust_stock(p_item uuid,p_location uuid,p_delta integer,p_reason text,p_actor uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare b public.mme_inventory_balances%rowtype; v integer;
begin
 if p_delta=0 or p_reason is null or length(trim(p_reason))<3 then raise exception 'valid_adjustment_required'; end if;
 insert into public.mme_inventory_balances(inventory_item_id,location_id,on_hand,reserved) values(p_item,p_location,0,0) on conflict(inventory_item_id,location_id) do nothing;
 select * into b from public.mme_inventory_balances where inventory_item_id=p_item and location_id=p_location for update;
 v:=b.on_hand+p_delta;
 if v<0 or v<b.reserved then raise exception 'insufficient_unreserved_stock'; end if;
 update public.mme_inventory_balances set on_hand=v,updated_at=now() where balance_id=b.balance_id;
 insert into public.mme_inventory_movements(inventory_item_id,from_location_id,to_location_id,movement_type,quantity,reason,actor_auth_user_id) values(p_item,case when p_delta<0 then p_location end,case when p_delta>0 then p_location end,case when p_delta>0 then 'adjustment_in' else 'adjustment_out' end,abs(p_delta),p_reason,p_actor);
 insert into public.mme_inventory_audit_events(entity_type,entity_id,action,actor_auth_user_id,metadata) values('inventory_item',p_item,'stock_adjusted',p_actor,jsonb_build_object('location_id',p_location,'delta',p_delta,'reason',p_reason));
 return jsonb_build_object('item_id',p_item,'location_id',p_location,'on_hand',v,'reserved',b.reserved);
end;$$;
revoke all on function public.mme_inventory_adjust_stock(uuid,uuid,integer,text,uuid) from public,anon,authenticated;
grant execute on function public.mme_inventory_adjust_stock(uuid,uuid,integer,text,uuid) to service_role;
do $$declare t text;begin foreach t in array array['mme_inventory_locations','mme_inventory_items','mme_inventory_serials','mme_inventory_balances','mme_inventory_movements','mme_inventory_reservations','mme_inventory_transfers','mme_inventory_transfer_lines','mme_inventory_counts','mme_inventory_count_lines','mme_inventory_receipts','mme_inventory_receipt_lines','mme_inventory_alerts','mme_inventory_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
commit;